// ─── Auth Helpers ─────────────────────────────────────────────────────────────

function issueToken(res: Response, payload: object): string {
  const token = jwt.sign(payload, JWT_SECRET, { expiresIn: "7d" });
  res.cookie(COOKIE_NAME, token, {
    httpOnly: true, secure: isProd, sameSite: isProd ? "strict" : "lax",
    maxAge: 7 * 24 * 60 * 60 * 1000, path: "/",
  });
  return token;
}

function safeUser(u: any) {
  const { password: _pw, ...rest } = u;
  return rest;
}

/**
 * Strip `correctAnswer` from every quiz question before sending to a
 * non-privileged caller.  Instructors and admins see the full object.
 *
 * IMPORTANT: server-side grading in POST /api/courses/:id/quiz and
 * POST /api/quiz/attempt reads directly from `state.courses` (never from
 * the sanitised response), so removing the field here does not break grading.
 */
function safeCourse(course: any, privileged = false): any {
  if (privileged) return course;
  const quizzes = (course.quizzes || []).map((quiz: any) => ({
    ...quiz,
    questions: (quiz.questions || []).map((q: any) => {
      const { correctAnswer: _ca, ...safe } = q;
      return safe;
    }),
  }));
  return { ...course, quizzes };
}

/**
 * Strip `correctAnswer` from every exam question for non-privileged callers.
 */
function safeExam(exam: any, privileged = false): any {
  if (privileged) return exam;
  const questions = (exam.questions || []).map((q: any) => {
    const { correctAnswer: _ca, ...safe } = q;
    return safe;
  });
  return { ...exam, questions };
}

// ─── Subscription plans ───────────────────────────────────────────────────────
// basic = free default, pro = 999 BDT, advanced = 1999 BDT.
// Paid plans are ONLY granted by an admin after a payment ID is verified.
const PLAN_PRICES_BDT: Record<string, number> = { basic: 0, pro: 999, advanced: 1999 };
function normalizePlan(p: unknown): "basic" | "pro" | "advanced" | null {
  const v = String(p ?? "").toLowerCase().trim();
  if (["basic", "free", "none", ""].includes(v)) return "basic";
  if (v === "pro" || v === "professional") return "pro";
  if (v === "advanced" || v === "enterprise" || v === "premium") return "advanced";
  return null;
}

