// Student submits a payment (transaction) ID for admin verification.
function createPaymentRequest(userId: string, planRaw: unknown, paymentIdRaw: unknown, methodRaw: unknown) {
  const plan = normalizePlan(planRaw);
  if (!plan || plan === "basic") return { error: "Choose pro or advanced plan" };
  const paymentId = String(paymentIdRaw ?? "").trim();
  if (!/^[A-Za-z0-9_\-]{6,40}$/.test(paymentId)) return { error: "Enter a valid payment/transaction ID (6-40 letters or digits)" };
  const dup = state.paymentRequests.find((r: any) => r.paymentId.toLowerCase() === paymentId.toLowerCase() && r.status !== "rejected");
  if (dup) return { error: "This payment ID has already been submitted" };
  const method = String(methodRaw ?? "bkash").slice(0, 20);
  const rec: any = {
    id: `pay_${Date.now()}_${Math.random().toString(36).slice(2, 7)}`,
    userId, plan, amount: PLAN_PRICES_BDT[plan], currency: "BDT",
    paymentId, method, status: "pending",
    submittedAt: new Date().toISOString(), reviewedAt: null, reviewedBy: null,
  };
  state.paymentRequests.push(rec);
  addLog(`Payment ID submitted for ${plan} plan`, "payment", userId);
  saveState();
  return { record: rec };
}

app.post("/api/subscription/payment-claim", (req: Request, res: Response) => {
  const session = requireSession(req, res);
  if (!session) return;
  const r: any = createPaymentRequest(session.userId, req.body?.planId, req.body?.paymentId, req.body?.method);
  if (r.error) { res.status(400).json({ error: r.error }); return; }
  res.status(201).json({ status: "pending", message: "Payment submitted. Access is granted once an admin verifies it.", request: r.record });
});

