function ensureCmsPages(cms: any): { pages: any[] } {
  const existingPages = Array.isArray(cms?.pages) ? cms.pages : [];
  const pages = DEFAULT_CMS_PAGES.map((defaultPage) => {
    const existing = existingPages.find((page: any) => page.id === defaultPage.id);
    if (!existing) return JSON.parse(JSON.stringify(defaultPage));
    const existingSections = Array.isArray(existing.sections) ? existing.sections : [];
    const sections = defaultPage.sections.map((defaultSection: any) => {
      const current = existingSections.find((section: any) => section.id === defaultSection.id);
      return current || JSON.parse(JSON.stringify(defaultSection));
    });
    const customSections = existingSections.filter((section: any) => !defaultPage.sections.some((item: any) => item.id === section.id));
    return { ...defaultPage, ...existing, sections: [...sections, ...customSections] };
  });
  const customPages = existingPages.filter((page: any) => !DEFAULT_CMS_PAGES.some((item) => item.id === page.id));
  return { ...(cms || {}), pages: [...pages, ...customPages] };
}

