app.post("/api/quiz/attempt", (req: Request, res: Response) => {
  const session = requireSession(req, res);
  if (!session) return;
  const { courseId, quizId, answers, timeTaken } = req.body;
  const course = state.courses.find((c: any) => c.id === courseId);
  const quiz = (course?.quizzes || []).find((q: any) => q.id === quizId);
  if (!quiz) { res.status(404).json({ error: "Quiz not found" }); return; }
  let correct = 0;
  // Internal breakdown used for logging/storage — includes correctAnswer
  const internalBreakdown = quiz.questions.map((q: any, i: number) => {
    const isCorrect = answers[i] === q.correctAnswer;
    if (isCorrect) correct++;
    return { questionId: q.id, selected: answers[i], correctAnswer: q.correctAnswer, isCorrect };
  });
  // Public breakdown returned to the student — correctAnswer deliberately omitted
  const publicBreakdown = internalBreakdown.map(({ correctAnswer: _ca, ...b }) => b);
  const score = Math.round((correct / quiz.questions.length) * 100);
  const passed = score >= (quiz.passingScore || 80);
  const attempt = {
    id: `qa_${Date.now()}`, userId: session.userId, courseId, quizId,
    quizTitle: quiz.title, score, passed, correct, total: quiz.questions.length,
    breakdown: internalBreakdown, // full detail stored server-side
    timeTaken: timeTaken || 0, attemptedAt: new Date().toISOString(),
  };
  state.quizAttempts.push(attempt);
  const enrollment = state.enrollments.find((e: any) => e.userId === session.userId && e.courseId === courseId);
  if (enrollment) {
    if (!enrollment.quizAttempts) enrollment.quizAttempts = {};
    enrollment.quizAttempts[quizId] = { score, passed, attemptedAt: attempt.attemptedAt };
  }
  addLog(`Quiz attempt: ${quiz.title} — ${score}%`, "quiz", session.userId);
  saveState();
  // Return the attempt to the student with correctAnswer stripped from breakdown
  res.json({ status: "success", attempt: { ...attempt, breakdown: publicBreakdown } });
});

app.get("/api/quiz/analytics", (req: Request, res: Response) => {
  const session = requireSession(req, res);
  if (!session) return;
  const isAdmin = session.role === "admin" || session.role === "super_admin";
  const isInstructor = session.role === "instructor";
  if (!isAdmin && !isInstructor) {
    res.status(403).json({ error: "Instructors and admins only" });
    return;
  }

  // Instructors only see attempts from courses they teach; admins see everything.
  let attempts = state.quizAttempts;
  if (isInstructor) {
    const myCourseIds = new Set(
      state.courses.filter((c: any) => c.instructorId === session.userId).map((c: any) => c.id)
    );
    attempts = attempts.filter((a: any) => myCourseIds.has(a.courseId));
  }
  const nameOf = (userId: string) =>
    state.users.find((u: any) => u.id === userId)?.name || "Student";
  // Answer breakdowns stay server-side — the analytics view only needs outcomes.
  const decorate = (a: any) => ({
    id: a.id, userId: a.userId, userName: nameOf(a.userId), courseId: a.courseId,
    quizId: a.quizId, quizTitle: a.quizTitle, score: a.score, passed: a.passed,
    correct: a.correct, total: a.total, attemptedAt: a.attemptedAt,
  });

  const totalAttempts = attempts.length;
  const passed = attempts.filter((a: any) => a.passed).length;
  const avgScore = totalAttempts > 0 ? Math.round(attempts.reduce((s: number, a: any) => s + a.score, 0) / totalAttempts) : 0;
  const byQuiz: Record<string, any> = {};
  for (const a of attempts) {
    if (!byQuiz[a.quizId]) byQuiz[a.quizId] = { title: a.quizTitle, attempts: 0, passed: 0, totalScore: 0 };
    byQuiz[a.quizId].attempts++;
    if (a.passed) byQuiz[a.quizId].passed++;
    byQuiz[a.quizId].totalScore += a.score;
  }
  const quizStats = Object.values(byQuiz).map((q: any) => ({ ...q, avgScore: Math.round(q.totalScore / q.attempts) }));
  res.json({
    totalAttempts, passed, failed: totalAttempts - passed, avgScore, quizStats,
    recentAttempts: attempts.slice(-20).reverse().map(decorate),
    scope: isInstructor ? "my_courses" : "platform",
  });
});

