// ─── Static / Production ──────────────────────────────────────────────────────

async function startServer(): Promise<void> {
  await initializeState();

  // ── Contact form ─────────────────────────────────────────────────────────
  app.post("/api/contact", async (req: Request, res: Response) => {
    const { name, email, message, planId, paymentId, method } = req.body;
    if (!name || !email || !message) {
      res.status(400).json({ error: "name, email and message are required" }); return;
    }
    // Payment verification request (signed-in users only)
    if (paymentId) {
      const sess = getSession(req);
      if (!sess) { res.status(401).json({ error: "Sign in to submit a payment ID" }); return; }
      const r: any = createPaymentRequest(sess.userId, planId, paymentId, method);
      if (r.error) { res.status(400).json({ error: r.error }); return; }
    }
    // Acknowledge sender
    sendContactAckEmail(email, name, message).catch(() => {});
    // Forward to admin inbox
    sendContactAckEmail("info@digitalmanufacturing.academy", `[Contact from ${name}]`, message).catch(() => {});
    addLog(`Contact form submitted by: ${name} <${email}>`, "contact", "guest");
    res.json({ status: "success" });
  });

  // ── Health check ─────────────────────────────────────────────────────────
  const _startTime = Date.now();
  app.get("/api/health", (_req: Request, res: Response) => {
    const uptimeSec = Math.floor((Date.now() - _startTime) / 1000);
    const uptimeStr = uptimeSec < 60
      ? `${uptimeSec}s`
      : uptimeSec < 3600
        ? `${Math.floor(uptimeSec / 60)}m ${uptimeSec % 60}s`
        : `${Math.floor(uptimeSec / 3600)}h ${Math.floor((uptimeSec % 3600) / 60)}m`;
    res.json({
      status:   "ok",
      storage:  isDatabaseAvailable() ? "postgresql" : "json",
      database: isDatabaseAvailable(),
      users:    state.users.length,
      courses:  state.courses.length,
      uptime:   uptimeStr,
      env:      process.env.NODE_ENV || "development",
      ts:       new Date().toISOString(),
    });
  });

  const distPath = path.join(process.cwd(), "dist");

  // ── Cache policy ────────────────────────────────────────────────────────────
  // Everything Vite emits under /assets is content-hashed, so it can be cached
  // for a year and marked immutable. The HTML shell always revalidates so a new
  // deploy can never point at a removed hash.
  const ONE_YEAR = 31536000;
  const cacheControlFor = (filePath: string): string =>
    filePath.includes(`${path.sep}assets${path.sep}`)
      ? `public, max-age=${ONE_YEAR}, immutable`
      : "public, max-age=0, must-revalidate";

  // ── Compression ─────────────────────────────────────────────────────────────
  // Hand-rolled gzip for the static build (no extra dependency): each file is
  // compressed once per version and reused in memory. This is what takes the
  // ~390KB main bundle and the ~145KB stylesheet down to a fraction of their
  // size on the wire, which is the biggest lever on payload-related audits.
  const GZIP_TYPES: Record<string, string> = {
    ".html": "text/html; charset=utf-8",
    ".js": "text/javascript; charset=utf-8",
    ".css": "text/css; charset=utf-8",
    ".json": "application/json; charset=utf-8",
    ".svg": "image/svg+xml",
    ".txt": "text/plain; charset=utf-8",
    ".xml": "application/xml; charset=utf-8",
    ".webmanifest": "application/manifest+json",
  };
  const GZIP_CACHE_MAX = 64;
  const gzipCache = new Map<string, { mtimeMs: number; buffer: Buffer }>();

  app.use((req: Request, res: Response, next: NextFunction) => {
    if (req.method !== "GET" || !/\bgzip\b/.test(String(req.headers["accept-encoding"] || ""))) {
      next();
      return;
    }
    let rel = decodeURIComponent(req.path).replace(/^\/+/, "");
    if (rel === "" || rel.endsWith("/")) rel += "index.html";
    const ext = path.extname(rel).toLowerCase();
    const type = GZIP_TYPES[ext];
    if (!type) { next(); return; }

    const filePath = path.join(distPath, rel);
    if (!filePath.startsWith(distPath + path.sep)) { next(); return; }

    let stat: fs.Stats;
    try { stat = fs.statSync(filePath); } catch { next(); return; }
    if (!stat.isFile()) { next(); return; }

    const send = (buffer: Buffer) => {
      res.setHeader("Content-Type", type);
      res.setHeader("Content-Encoding", "gzip");
      res.setHeader("Vary", "Accept-Encoding");
      res.setHeader("Content-Length", String(buffer.length));
      res.setHeader("Cache-Control", cacheControlFor(filePath));
      res.end(buffer);
    };

    const cached = gzipCache.get(filePath);
    if (cached && cached.mtimeMs === stat.mtimeMs) { send(cached.buffer); return; }

    fs.readFile(filePath, (readErr, data) => {
      if (readErr) { next(); return; }
      zlib.gzip(data, (gzErr, buffer) => {
        if (gzErr || !buffer) { next(); return; }
        gzipCache.set(filePath, { mtimeMs: stat.mtimeMs, buffer });
        if (gzipCache.size > GZIP_CACHE_MAX) {
          const oldest = gzipCache.keys().next().value;
          if (oldest !== undefined) gzipCache.delete(oldest);
        }
        send(buffer);
      });
    });
  });

  app.use(express.static(distPath, {
    setHeaders: (res, filePath) => {
      res.setHeader("Cache-Control", cacheControlFor(filePath));
    },
  }));

  // A missing build asset must 404 instead of falling through to the SPA shell.
  // Serving index.html (200, text/html) for a hashed bundle makes the browser
  // refuse to execute it and the whole app goes blank with no visible error.
  app.get(["/assets/*", "*.js", "*.css", "*.map", "*.webmanifest"], (_req: Request, res: Response) => {
    res.status(404).type("text/plain").send("Static asset not found — the deployed build is out of date.");
  });

  app.get("*", (_req: Request, res: Response) => {
    res.setHeader("Cache-Control", "public, max-age=0, must-revalidate");
    res.sendFile(path.join(distPath, "index.html"));
  });

  // ── Global Express error handler (4-arg signature required by Express) ─────
  // Catches any error thrown or next(err)'d inside a route handler.
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  app.use((err: Error, _req: Request, res: Response, _next: NextFunction) => {
    const ref = `err_${Date.now()}`;
    recordError(`express[${ref}]`, err);
    // Never leak stack traces to clients in production
    const detail = isProd ? undefined : err.message;
    res.status(500).json({ error: "Internal server error", ref, ...(detail ? { detail } : {}) });
  });

  const httpServer = app.listen(PORT, "0.0.0.0", () => {
    console.log(`[DMA SERVER] Academy running on http://0.0.0.0:${PORT}`);
    console.log(`[DMA SERVER] Storage: ${isDatabaseAvailable() ? "PostgreSQL" : "local JSON (development only)"}`);
  });

  const shutdown = (signal: NodeJS.Signals) => {
    console.info(`[DMA SERVER] Received ${signal}; waiting for requests and database writes to finish`);
    httpServer.close(error => {
      if (error) {
        console.error("[DMA SERVER] Error while closing HTTP server", error);
        process.exitCode = 1;
      }
      disconnectDatabase().catch(error => {
        console.error("[DB] Error while closing PostgreSQL connection", error);
        process.exitCode = 1;
      });
    });
  };
  process.once("SIGTERM", shutdown);
  process.once("SIGINT", shutdown);
}

// ─── Production Error Monitoring ─────────────────────────────────────────────

const _errorCounts: Record<string, number> = {};

function recordError(label: string, err: unknown): void {
  const msg = err instanceof Error ? err.message : String(err);
  const key = `${label}:${msg}`;
  _errorCounts[key] = (_errorCounts[key] || 0) + 1;
  // Basic rate-limiting: only log once per minute for identical errors
  if (_errorCounts[key] === 1 || _errorCounts[key] % 60 === 0) {
    console.error(`[DMA][${label}] (×${_errorCounts[key]}) ${msg}`, err instanceof Error ? err.stack : "");
    addLog(`Server error [${label}]: ${msg}`, "server_error");
  }
}

process.on("uncaughtException", (err) => recordError("uncaughtException", err));
process.on("unhandledRejection", (reason) => recordError("unhandledRejection", reason));

startServer();
